#!/usr/bin/env node
// ── design-system/_ds_bundle.js ──────────────────────────────────────────────
// The DS demo pages — ui_kits/app/index.html and the three *.card.html — load
// `_ds_bundle.js` and read the components off a `DadStrength*` global. Claude
// Design generates that bundle at view time from components/**/*.jsx and does
// not store it in the project, so a vendored copy has to build its own or the
// demos render blank (Codex, round 2).
//
// This builds it: every component in core/, progress/ and training/, bundled
// as an IIFE that assigns `DadStrengthDS`, with `react` shimmed to the
// `window.React` the pages already load from the CDN. The sources' hash is
// stamped into the banner, and scripts/checks/design-system.mjs fails when the
// stamp no longer matches the sources — so re-vendoring without rebuilding
// cannot ship a stale bundle.
//
//   npm run design-system:bundle
// ─────────────────────────────────────────────────────────────────────────────
import { build } from 'esbuild'
import { readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { componentSources, sourcesDigest } from './checks/design-system-sources.mjs'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const DS = join(ROOT, 'design-system')

const files = componentSources(DS)
const names = files.map((f) => f.split('/').pop().replace(/\.jsx$/, ''))
const digest = sourcesDigest(DS, files)

const entry = files.map((f, i) => `export { ${names[i]} } from './${f}'`).join('\n') + '\n'

// `import React from "react"` in every component → the React the page loaded.
const reactShim = {
  name: 'react-shim',
  setup(b) {
    b.onResolve({ filter: /^react$/ }, () => ({ path: 'react', namespace: 'react-shim' }))
    b.onLoad({ filter: /.*/, namespace: 'react-shim' }, () => ({
      loader: 'js',
      contents: 'const R = window.React;\nexport default R;\nexport const { useState, useEffect, useMemo, useRef, useCallback, Fragment } = R;\n',
    }))
  },
}

const result = await build({
  stdin: { contents: entry, resolveDir: DS, loader: 'js', sourcefile: '_ds_entry.js' },
  bundle: true,
  write: false,
  format: 'iife',
  globalName: 'DadStrengthDS',
  target: 'es2018',
  // The classic transform, on purpose, and the repo tsconfig's `react-jsx`
  // overridden: the automatic runtime would bundle node_modules' React 19
  // jsx-runtime against the React 18 the demo pages load from the CDN, and
  // React 18 does not recognise React 19 elements. React.createElement from
  // the page's own React is the only thing that works everywhere.
  jsx: 'transform',
  tsconfigRaw: '{"compilerOptions":{"jsx":"react"}}',
  legalComments: 'none',
  plugins: [reactShim],
})

if (/jsx[-_]runtime/.test(result.outputFiles[0].text)) {
  throw new Error('the bundle pulled in a jsx-runtime; it must use React.createElement from window.React only')
}

const banner = [
  '// GENERATED by scripts/design-system-bundle.mjs from design-system/components/**/*.jsx — do not edit.',
  '// Regenerate after re-vendoring: npm run design-system:bundle',
  '// sources: ' + digest,
  '',
].join('\n')

const out = join(DS, '_ds_bundle.js')
writeFileSync(out, banner + result.outputFiles[0].text)
console.log('design-system/_ds_bundle.js — ' + names.length + ' components, ' + readFileSync(out).length + ' bytes, sources ' + digest)
